/**
 * 指纹比对：完全相等即同参；对含精确请求时刻的指纹（最后一段为 epoch 毫秒），
 * 仅时刻段差异视为同一逻辑请求的重放，其余业务参数不同仍判异参 409。
 */
private boolean sameFingerprint(String stored, String candidate) {
    if (stored.equals(candidate)) {
        return true;
    }
    int storedCut = stored.lastIndexOf('|');
    int candidateCut = candidate.lastIndexOf('|');
    if (storedCut <= 0 || storedCut != candidateCut) {
        return false;
    }
    if (!stored.substring(0, storedCut).equals(candidate.substring(0, candidateCut))) {
        return false;
    }
    return isEpochMillis(stored.substring(storedCut + 1))
            && isEpochMillis(candidate.substring(candidateCut + 1));
}

private boolean isEpochMillis(String value) {
    if (value == null || value.isBlank()) {
        return false;
    }
    for (int i = 0; i < value.length(); i++) {
        if (!Character.isDigit(value.charAt(i))) {
            return false;
        }
    }
    return true;
}

